#!/usr/bin/env python3
"""Port fog charger + fuel gauge DT nodes into the nopmi board dtsi files.

Ground truth: live /proc/device-tree of Redmi 10C (fog, khaje-idp-nopmi) and
r0ddty/kernel_xiaomi_fog. Without these nodes the CI kernel boots with no
charger (smb1351) and no fuel gauge (sh366101) driver at all."""
