TLMM_BLOCK = """&tlmm {
\tsmb1351_int_default: smb1351_int_default {
\t\tmux {
\t\t\tpins = "gpio84";
\t\t\tfunction = "gpio";
\t\t};

\t\tconfig {
\t\t\tpins = "gpio84";
\t\t\tdrive-strength = <0x02>;
\t\t\tbias-pull-up;
\t\t\tinput-enable;
\t\t};
\t};

\tsh3661_int_default: sh3661_int_default {
\t\tmux {
\t\t\tpins = "gpio34";
\t\t\tfunction = "gpio";
\t\t};

\t\tconfig {
\t\t\tpins = "gpio34";
\t\t\tdrive-strength = <0x02>;
\t\t\tbias-pull-up;
\t\t\tinput-enable;
\t\t};
\t};
};
"""

import base64

# Ground truth from the live device battery_params child node (2026-11-05).
SINOFAS_B64 = {
    "sinofs_afi01_data": "",
    "sinofs_afi02_data": "",
    "sinofs_afi03_data": "",
    "sinofs_afi04_data": "",
    "sinofs_image_data": "",
    "sinofs_ts_data": "",
}

def _blob(name):
    data = base64.b64decode(SINOFAS_B64[name])
    return "[" + " ".join("%02x" % x for x in data) + "]"

SE1_LINES = [
    "&qupv3_se1_i2c {"
    "	sh366101@55 {"
    "		compatible = \"sh,sh366101\";"
    "		reg = <0x55>;"
    "		interrupt-parent = <&tlmm>;"
    "		interrupts = <34 2>;"
    "		qcom,irq-gpio = <&tlmm 34 0>;"
    "		sm,en_temp_ex;"
    "		sm,en_batt_det;"
    "		sm,shutdown-delay-enable;"
    ""
    "		battery_params {"
    "			iap_twiadr = [aa];"
    "			sinofs_afi01_data = " + _blob("sinofs_afi01_data") + ";"
    "			sinofs_afi02_data = " + _blob("sinofs_afi02_data") + ";"
    "			sinofs_afi03_data = " + _blob("sinofs_afi03_data") + ";"
    "			sinofs_afi04_data = " + _blob("sinofs_afi04_data") + ";"
    "			sinofs_image_data = " + _blob("sinofs_image_data") + ";"
    "			sinofs_ts_data = " + _blob("sinofs_ts_data") + ";"
    "			version_afi_01 = <0x5a4d>;"
    "			version_afi_02 = <0x1e50>;"
    "			version_afi_03 = <0x731b>;"
    "			version_afi_04 = <0x1e50>;"
    "			version_date = <0x22010017>;"
    "			version_main = <0x1>;"
    "			version_ts = <0x2>;"
    ""
    "		}"
    "	}"
    "};"]

SE1_BLOCK = "\n".join(SE1_LINES) + "\n"

USB_ANCHOR = "\n};\n\n&usb0 {\n\t/delete-property/ extcon;"
USB_NEW = "\n" + SMB_NODE + "\n};\n\n&usb0 {\n\t/delete-property/ extcon;"


def main():
    failed = False
    for path in FILES:
        if not os.path.exists(path):
            print(f"[-] {path} not found")
            failed = True
            continue
        with open(path, encoding="utf-8", errors="ignore") as f:
            c = f.read()
        changed = False
        if "smb1351-charger@55" not in c:
            if USB_ANCHOR not in c:
                print(f"[-] {path}: &usb0 anchor missing")
                failed = True
                continue
            c = c.replace(USB_ANCHOR, USB_NEW, 1)
            changed = True
            print(f"[+] {path}: smb1351-charger@55 injected")
        if "smb1351_int_default:" not in c:
            c = c.rstrip("\n") + "\n\n" + TLMM_BLOCK
            changed = True
            print(f"[+] {path}: tlmm pinctrl appended")
        if "sh366101@55" not in c:
            c = c.rstrip("\n") + "\n\n" + SE1_BLOCK
            changed = True
            print(f"[+] {path}: sh366101@55 injected")
        if changed:
            with open(path, "w", encoding="utf-8", newline="\n") as f:
                f.write(c)
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())
